// Fixed scraper for gamma.app with proper Puppeteer API compatibility
const url = $input.first().json.job_description_url;

try {
  console.log(`Attempting to scrape: ${url}`);

  // Set a realistic user agent and viewport
  await $page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
  await $page.setViewport({ width: 1920, height: 1080 });

  // Add extra headers to appear more like a real browser
  await $page.setExtraHTTPHeaders({
    'Accept-Language': 'en-US,en;q=0.9',
    'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8'
  });

  // Navigate with a single, reliable strategy
  await $page.goto(url, { 
    waitUntil: 'networkidle2', 
    timeout: 45000 
  });

  console.log('Navigation successful');

  // Wait for page to stabilize using Promise-based delay instead of waitForTimeout
  await new Promise(resolve => setTimeout(resolve, 5000));

  // Check if we're on the right page
  const currentUrl = $page.url();
  const pageTitle = await $page.title();
  console.log(`Page loaded: ${pageTitle} at ${currentUrl}`);

  if (!currentUrl.includes('gamma.app')) {
    throw new Error(`Redirected away from gamma.app to: ${currentUrl}`);
  }

  // Multiple strategies to find content
  let content = null;
  let method = null;

  // Strategy 1: Look for gamma-specific content containers
  const gammaSelectors = [
    '[data-testid="presentation-content"]',
    '[data-testid="slide-content"]',
    '.slide-content',
    '.presentation-content',
    '[role="document"]',
    '[data-doc-content]',
    '.doc-content',
    '.gamma-content'
  ];

  for (const selector of gammaSelectors) {
    try {
      // Use waitForSelector with proper error handling
      await $page.waitForSelector(selector, { timeout: 8000 });
      const element = await $page.$(selector);
      if (element) {
        content = await $page.evaluate(el => el.innerText.trim(), element);
        method = `gamma_selector: ${selector}`;
        console.log(`Found content using: ${selector}, length: ${content.length}`);
        if (content && content.length > 100) break;
      }
    } catch (e) {
      console.log(`Selector ${selector} not found or failed: ${e.message}`);
    }
  }

  // Strategy 2: Look for generic content areas
  if (!content || content.length < 100) {
    console.log('Trying generic selectors...');
    const genericSelectors = [
      'main',
      '[role="main"]',
      'article',
      '.main-content',
      '#content',
      '.content'
    ];

    for (const selector of genericSelectors) {
      try {
        const element = await $page.$(selector);
        if (element) {
          const text = await $page.evaluate(el => el.innerText.trim(), element);
          if (text && text.length > (content?.length || 0)) {
            content = text;
            method = `generic_selector: ${selector}`;
            console.log(`Better content found using: ${selector}, length: ${text.length}`);
          }
        }
      } catch (e) {
        console.log(`Generic selector ${selector} failed: ${e.message}`);
      }
    }
  }

  // Strategy 3: Extract all text content from body with filtering
  if (!content || content.length < 200) {
    console.log('Trying comprehensive text extraction...');
    try {
      content = await $page.evaluate(() => {
        // Remove unwanted elements
        const unwantedSelectors = [
          'script', 'style', 'nav', 'header', 'footer', 
          '.nav', '.header', '.footer', '.sidebar',
          '[class*="navigation"]', '[class*="menu"]',
          '.ad', '.advertisement', '.cookie'
        ];

        unwantedSelectors.forEach(selector => {
          const elements = document.querySelectorAll(selector);
          elements.forEach(el => el.remove());
        });

        // Look for the main content area
        const contentSelectors = [
          '[class*="slide"]', '[class*="content"]', 'main', 
          '[role="main"]', 'article', '.presentation'
        ];

        let bestContent = '';
        let maxLength = 0;

        contentSelectors.forEach(selector => {
          try {
            const elements = document.querySelectorAll(selector);
            elements.forEach(el => {
              const text = el.innerText?.trim() || '';
              if (text.length > maxLength && text.length > 100) {
                maxLength = text.length;
                bestContent = text;
              }
            });
          } catch (e) {
            console.log('Error with selector:', selector, e.message);
          }
        });

        // If no good content found, try body text but filter it
        if (!bestContent || bestContent.length < 100) {
          const bodyText = document.body.innerText || '';
          // Remove common navigation/UI text
          const filtered = bodyText
            .split('\n')
            .filter(line => {
              const l = line.trim().toLowerCase();
              return l.length > 10 && 
                     !l.includes('cookie') && 
                     !l.includes('menu') && 
                     !l.includes('navigation') &&
                     !l.startsWith('sign in') &&
                     !l.startsWith('log in');
            })
            .join('\n');
          bestContent = filtered;
        }

        return bestContent.trim();
      });
      method = 'comprehensive_extraction';
      console.log(`Comprehensive extraction result length: ${content?.length || 0}`);
    } catch (evalError) {
      console.log('Comprehensive extraction failed:', evalError.message);
    }
  }

  // Clean and validate content
  if (content && content.length > 50) {
    // Clean up the content
    content = content
      .replace(/\n\s*\n\s*\n/g, '\n\n')
      .replace(/\t+/g, ' ')
      .replace(/\s{3,}/g, ' ')
      .trim();

    // Check if content looks relevant
    const jobKeywords = [
      'responsibilities', 'requirements', 'experience', 'skills', 
      'qualifications', 'role', 'position', 'candidate', 'job',
      'work', 'team', 'company', 'duties', 'tasks'
    ];

    const contentLower = content.toLowerCase();
    const keywordMatches = jobKeywords.filter(keyword => 
      contentLower.includes(keyword)
    );

    return [{
      ...$json,
      job_description_text: content,
      scraper_status: 'success',
      extraction_method: method,
      content_length: content.length,
      keyword_matches: keywordMatches,
      keywords_found: keywordMatches.length,
      final_url: currentUrl,
      page_title: pageTitle
    }];

  } else {
    // Take basic screenshot for debugging (no quality parameter)
    let screenshot = null;
    try {
      screenshot = await $page.screenshot({ 
        encoding: 'base64',
        fullPage: true
      });
    } catch (screenshotError) {
      console.error('Screenshot failed:', screenshotError.message);
    }

    // Get page source sample for debugging
    const pageHtml = await $page.content();
    const htmlSample = pageHtml.substring(0, 1000);

    return [{
      ...$json,
      job_description_text: null,
      error: `Content too short or empty. Length: ${content?.length || 0}`,
      scraper_status: 'failed',
      extraction_method: method,
      content_preview: content?.substring(0, 200) || null,
      page_title: pageTitle,
      final_url: currentUrl,
      html_sample: htmlSample,
      debug_screenshot: screenshot
    }];
  }

} catch (error) {
  console.error('Scraping error:', error.message);

  // Enhanced error information
  let debugInfo = {
    error_type: error.name,
    error_message: error.message,
    timestamp: new Date().toISOString()
  };

  // Try to get current page info even if failed
  try {
    debugInfo.current_url = await $page.url();
    debugInfo.page_title = await $page.title();
  } catch (e) {
    debugInfo.page_info_error = e.message;
  }

  // Take basic screenshot if possible (no quality parameter)
  let screenshot = null;
  try {
    screenshot = await $page.screenshot({ 
      encoding: 'base64',
      fullPage: false
    });
  } catch (screenshotError) {
    debugInfo.screenshot_error = screenshotError.message;
  }

  return [{
    ...$json,
    job_description_text: null,
    error: `Scraping failed: ${error.message}`,
    scraper_status: 'error',
    debug_info: debugInfo,
    debug_screenshot: screenshot
  }];
}

