// Fixed Error Handler - properly formats output for n8n
const result = $input.all()[0].json;

// Add timestamp
result.last_scraped = new Date().toISOString();

// Make sure scraper_status exists
if (!result.scraper_status) {
  result.scraper_status = 'failed';
  result.error_message = result.error_message || 'Unknown error';
}

// Return the cleaned output
return [{ json: result }];

return $input.all().map(item => {
    const data = item.json;
    const text = data.job_description_text || "";

    // Improved section extraction with better boundary detection and section identification
    function extractSection(headings) {
        const headingArray = Array.isArray(headings) ? headings : [headings];

        for (const heading of headingArray) {
            // Try exact section match first
            const exactRegex = new RegExp(
                `(?:^|\\n)\\s*(${heading})\\s*:?\\s*\\n([\\s\\S]*?)(?=\\n\\s*(?:[A-Z][a-zA-Z\\s&/]*:|Expand|Position Description|Compensation|Apply Now|$))`, 
                'i'
            );
            const exactMatch = text.match(exactRegex);
            if (exactMatch && exactMatch[2] && exactMatch[2].trim().length > 50) {
                return exactMatch[2]
                    .replace(/Expand/gi, '')
                    .replace(/\n+/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();
            }

            // Fallback to looser matching
            const looseRegex = new RegExp(
                `(${heading})\\s*:?\\s*([\\s\\S]*?)(?=(\\n\\s*(?:Expand|[A-Z][a-zA-Z\\s&/]*:|Position Description|Qualifications|Requirements|Benefits|Compensation|About|Key Responsibilities|Mission|Overview))|$)`, 
                'i'
            );
            const looseMatch = text.match(looseRegex);
            if (looseMatch && looseMatch[2] && looseMatch[2].trim().length > 20) {
                return looseMatch[2]
                    .replace(/Expand/gi, '')
                    .replace(/\n+/g, ' ')
                    .replace(/\s+/g, ' ')
                    .trim();
            }
        }
        return '';
    }

    // Enhanced section extraction with more comprehensive headings
    const responsibilities = extractSection([
        "Key Responsibilities",
        "Responsibilities", 
        "What You'll Do",
        "Your Role",
        "Job Responsibilities",
        "Main Duties",
        "Primary Responsibilities"
    ]);

    const requirements = extractSection([
        "Requirements",
        "Qualifications", 
        "What We're Looking For",
        "Skills Required",
        "Technical Requirements",
        "Must Have",
        "Essential Skills"
    ]);

    const roleOverview = extractSection([
        "Role Overview",
        "Position Overview", 
        "Job Overview",
        "About the Role",
        "Mission",
        "Job Summary"
    ]);

    const companyInfo = extractSection([
        "About The Company",
        "Company Overview",
        "About Us",
        "Our Company",
        "Company Background"
    ]);

    const positionDesc = extractSection([
        "Position Description",
        "Job Details",
        "Work Schedule",
        "Employment Details",
        "Working Conditions"
    ]);

    // Enhanced skills extraction with more comprehensive patterns
    const combinedText = `${responsibilities}\n${requirements}\n${text}`;

    // More comprehensive technical skills patterns
    const technicalSkills = [];
    const techPatterns = [
        // Frontend Technologies
        /\b(React|Vue\.?js|Angular|Svelte|Next\.js|Nuxt\.js|Gatsby|TypeScript|JavaScript|jQuery|Bootstrap|Tailwind|Sass|SCSS|Less)\b/gi,
        // Backend Technologies
        /\b(Node\.js|Express|Fastify|PHP|Laravel|Symfony|Python|Django|Flask|Java|Spring|C#|\.NET|Ruby|Rails|Go|Rust|Kotlin)\b/gi,
        // Databases
        /\b(MySQL|PostgreSQL|MongoDB|Redis|Elasticsearch|DynamoDB|Cassandra|SQLite|MariaDB|Oracle|SQL Server)\b/gi,
        // Cloud & DevOps
        /\b(AWS|Azure|Google Cloud|GCP|Docker|Kubernetes|Jenkins|GitLab CI|GitHub Actions|Terraform|Ansible|Vagrant)\b/gi,
        // Tools & Platforms
        /\b(Git|GitHub|GitLab|Bitbucket|Jira|Confluence|Slack|Postman|Insomnia|Figma|Adobe XD)\b/gi,
        // Email & Marketing Tools
        /\b(Postfix|OpenSMTPD|Sendmail|Mailgun|SendGrid|Amazon SES|SPF|DKIM|DMARC|SMTP)\b/gi,
        // Monitoring & Analytics
        /\b(Prometheus|Grafana|ELK Stack|New Relic|DataDog|Google Analytics|Mixpanel)\b/gi,
        // Integration & Automation specific skills
        /\b(API|APIs|webhook|webhooks|payment gateway|payment gateways|SaaS|integration|integrations|automation|checkout|billing|technical integration)\b/gi,
        // General technical skills
        /\b(web technologies|embedding scripts|callbacks|custom checkout flows|problem-solving|technical documentation|process improvement)\b/gi
    ];

    techPatterns.forEach(pattern => {
        const matches = combinedText.match(pattern) || [];
        technicalSkills.push(...matches);
    });

    // Additional skill extraction from common phrases
    const skillPhrases = [
        /experience in ([^,\.]+(?:integration|API|payment|automation|technical)[^,\.]*)/gi,
        /proficiency with ([^,\.]+)/gi,
        /understanding of ([^,\.]+)/gi,
        /working with ([^,\.]+)/gi,
        /knowledge of ([^,\.]+)/gi
    ];

    skillPhrases.forEach(pattern => {
        const matches = combinedText.matchAll(pattern);
        for (const match of matches) {
            if (match[1]) {
                technicalSkills.push(match[1].trim());
            }
        }
    });

    const uniqueSkills = Array.from(new Set(technicalSkills.map(s => s.toLowerCase().replace(/\s+/g, ' '))))
        .filter(skill => skill.length > 2 && skill.length < 50) // Filter out too short or too long matches
        .map(s => s.split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' '))
        .sort()
        .join(', ');

    // Enhanced tools extraction with more comprehensive list
    const toolsMatch = combinedText.match(/\b(N8N|Zapier|Make|Webhooks|GoHighLevel|ClickFunnels|Webflow|Framer|HubSpot|Contentful|Strapi|Sanity|Docker|AWS|Postman|Jest|Cypress|Selenium|Ansible|Terraform|Kubernetes|Jenkins|Grafana|Prometheus|ELK|Linux|Ubuntu|Debian|FoundationDB|DigitalOcean|Hetzner)\b/gi) || [];
    const tools = Array.from(new Set(toolsMatch.map(t => t.toLowerCase())))
        .map(t => t.charAt(0).toUpperCase() + t.slice(1))
        .sort()
        .join(', ');

    // Enhanced platforms extraction
    const platformsMatch = combinedText.match(/\b(GoHighLevel|ClickFunnels|WordPress|Shopify|Webflow|Framer|SaaS|AWS|Azure|Google Cloud|DigitalOcean|Hetzner|Linux|Ubuntu|Debian)\b/gi) || [];
    const platforms = Array.from(new Set(platformsMatch.map(p => p.toLowerCase())))
        .map(p => p.charAt(0).toUpperCase() + p.slice(1))
        .sort()
        .join(', ');

    // Enhanced programming languages extraction
    const progLangs = combinedText.match(/\b(JavaScript|TypeScript|Python|PHP|Java|C#|Ruby|Go|Rust|SQL|HTML|CSS|Shell|Bash|PowerShell)\b/gi) || [];
    const programmingLanguages = Array.from(new Set(progLangs.map(l => l.toLowerCase())))
        .map(l => l.charAt(0).toUpperCase() + l.slice(1))
        .sort()
        .join(', ');

    // Enhanced salary extraction with more specific patterns
    const salaryPatterns = [
        /Compensation[:\s]*\$?([\d,]+(?:\.\d+)?)\s*(?:-|to)\s*\$?([\d,]+(?:\.\d+)?)(?:\s*\(starting salary\))?/i,
        /Salary[:\s]*\$?([\d,]+(?:\.\d+)?)\s*(?:-|to)\s*\$?([\d,]+(?:\.\d+)?)(?:\s*\(starting salary\))?/i,
        /Compensation[:\s]*\$?([\d,]+(?:\.\d+)?)\+?(?:\s*\(starting salary\))?/i,
        /Salary[:\s]*\$?([\d,]+(?:\.\d+)?)\+?(?:\s*\(starting salary\))?/i,
        /\$?([\d,]+(?:\.\d+)?)\+?(?:\s*\(starting salary\))/i,
        /\$?([\d,]+(?:\.\d+)?)(?:\s*per\s*month|\s*\/month|\s*monthly)/i,
        /Range[:\s]*\$?([\d,]+(?:\.\d+)?)\+?/i
    ];

    let salary = '';
    for (const pattern of salaryPatterns) {
        const match = text.match(pattern);
        if (match && parseInt(match[1].replace(/,/g, '')) >= 1000) { // Only match salaries >= 1000 to avoid years
            if (match[2]) {
                // Range found
                salary = `${match[1]} - ${match[2]}`;
            } else {
                salary = match[1].includes('+') || text.includes('starting salary') ? `${match[1]}+` : `${match[1]}`;
            }
            break;
        }
    }

    // Enhanced working hours extraction with better time parsing
    const hoursMatch = text.match(/(\d+)\s*hours?\s*per\s*day/i);
    const timeRangeMatch = text.match(/(?:between\s+)?(\d+(?::\d+)?\s*(?:AM|PM))\s*(?:to|till|–|-)\s*(\d+(?::\d+)?\s*(?:AM|PM))/i) ||
                          text.match(/(\d+\s*(?:AM|PM))\s*(?:to|till|–|-)\s*(\d+\s*(?:AM|PM))/i);

    let hoursPerDay = 0;
    let workingHours = '';

    if (hoursMatch) {
        hoursPerDay = parseInt(hoursMatch[1]);
    }

    if (timeRangeMatch) {
        workingHours = `${timeRangeMatch[1]} - ${timeRangeMatch[2]}`;

        // Calculate hours if not explicitly stated
        if (!hoursPerDay) {
            const start = timeRangeMatch[1].toLowerCase();
            const end = timeRangeMatch[2].toLowerCase();

            // Parse time components
            const startHour = parseInt(start.replace(/[^\d]/g, ''));
            const endHour = parseInt(end.replace(/[^\d]/g, ''));
            const startIsPM = start.includes('pm');
            const endIsPM = end.includes('pm');
            const startIsAM = start.includes('am');
            const endIsAM = end.includes('am');

            // Convert to 24-hour format
            let start24 = startHour;
            let end24 = endHour;

            if (startIsPM && startHour !== 12) start24 += 12;
            if (startIsAM && startHour === 12) start24 = 0;
            if (endIsPM && endHour !== 12) end24 += 12;
            if (endIsAM && endHour === 12) end24 = 0;

            // Calculate duration
            if (end24 > start24) {
                hoursPerDay = end24 - start24;
            } else if (end24 < start24) {
                // Crosses midnight
                hoursPerDay = (24 - start24) + end24;
            }
        }
    }

    // Enhanced timezone extraction
    const timezoneMatch = text.match(/\b([A-Z]{2,4})\s*time\b/i) || 
                         text.match(/\b(Lebanon|Leb)\s*time\b/i) ||
                         text.match(/\b(EST|PST|GMT|UTC|CET)\b/i);
    let timezone = '';
    if (timezoneMatch) {
        timezone = timezoneMatch[1] === 'Leb' || timezoneMatch[1] === 'Lebanon' ? 'Lebanon time' : timezoneMatch[1] + ' time';
    }

    // Enhanced location extraction
    const locationPatterns = [
        /work from ([\w\s,]+?)(?:\s*[.-]|\.|$)/i,
        /freedom to work from ([\w\s,]+?)(?:\s*[.-]|$)/i,
        /location[:\s]*([\w\s,]+?)(?:\s*[.-]|$)/i,
        /based in ([\w\s,]+?)(?:\s*[.-]|$)/i
    ];

    let location = '';
    for (const pattern of locationPatterns) {
        const match = text.match(pattern);
        if (match) {
            location = match[1].trim();
            break;
        }
    }

    // Enhanced remote status detection
    let remoteStatus = 'On-site';
    if (/remote|work from anywhere|freedom to work from|work remotely/i.test(text)) {
        remoteStatus = 'Remote';
    } else if (/hybrid|flexible|part remote/i.test(text)) {
        remoteStatus = 'Hybrid';
    }

    // Enhanced working days extraction
    const workingDaysMatch = text.match(/(\d+)\s*days?\s*(?:a\s*|per\s*)?week/i) ||
                            text.match(/Monday[^.]*Friday|Mon[^.]*Fri/i) ||
                            text.match(/(5|five)\s*days/i);
    let workingDays = '';
    if (workingDaysMatch) {
        if (workingDaysMatch[1] && !isNaN(workingDaysMatch[1])) {
            workingDays = `${workingDaysMatch[1]} days per week`;
        } else if (/Monday.*Friday|Mon.*Fri|5|five/i.test(workingDaysMatch[0])) {
            workingDays = '5 days per week';
        } else {
            workingDays = workingDaysMatch[0];
        }
    }

    // Enhanced company size extraction
    const companySizeMatch = text.match(/user base exceeding ([\d,]+(?:\.\d+)?)\s*(?:million|k)?\s*(?:monthly\s*)?active users/i) || 
                             text.match(/([\d,]+(?:\.\d+)?)\s*(?:million|k)?\s*users/i) ||
                             text.match(/([\d,]+)\s*employees/i) ||
                             text.match(/(small|medium|large|startup|enterprise)\s*(?:company|business|team)/i);
    const companySize = companySizeMatch ? companySizeMatch[1] : '';

    // Enhanced industry extraction
    const industryMatch = text.match(/\b(digital commerce|e-commerce|SaaS|technology|internet businesses|marketing|advertising|fintech|healthcare|education|retail|AI|artificial intelligence|automation|DevOps|cloud computing)\b/i);
    const industry = industryMatch ? industryMatch[1] : '';

    // Enhanced milestones extraction
    const milestonesPattern = /Within\s*\d+\s*days:[^.]*\.?|First\s*\d+\s*days:[^.]*\.?/gi;
    const milestonesMatches = text.match(milestonesPattern) || [];
    const milestones = milestonesMatches.join(' ; ');

    // Enhanced benefits and time-off extraction
    const benefitsPattern = /Benefits?[:\s]*([\s\S]*?)(?=\n\s*[A-Z][^:\n]*:|Position Description|Compensation|$)/i;
    const benefitsMatch = text.match(benefitsPattern);

    // Extract vacation and time-off policies
    const vacationPatterns = [
        /(\d+)\s*(?:weeks?|days?)\s*(?:of\s*)?(?:paid\s*)?(?:vacation|PTO|time off|leave)/gi,
        /unlimited\s*(?:vacation|PTO|time off)/gi,
        /flexible\s*(?:vacation|PTO|time off)/gi,
        /may request time off(?:\s*anytime)?(?:\s*with\s*(?:advanced\s*)?notice)?/gi,
        /can request\s*(?:vacation|time off|leave)/gi,
        /(?:vacation|PTO|time off)\s*policy/gi
    ];

    const vacationBenefits = [];
    vacationPatterns.forEach(pattern => {
        const matches = text.match(pattern) || [];
        vacationBenefits.push(...matches);
    });

    // Extract general benefits
    const generalBenefitsMatch = text.match(/health|insurance|dental|401k|equity|stock options|retirement|medical|vision/gi) || [];

    // Combine all benefits
    let benefits = '';
    const allBenefits = [];

    if (benefitsMatch && benefitsMatch[1]) {
        allBenefits.push(benefitsMatch[1].replace(/\n+/g, ' ').trim());
    }

    if (vacationBenefits.length > 0) {
        allBenefits.push(...vacationBenefits);
    }

    if (generalBenefitsMatch.length > 0) {
        allBenefits.push(...generalBenefitsMatch);
    }

    benefits = Array.from(new Set(allBenefits.map(b => b.toLowerCase())))
        .map(b => b.charAt(0).toUpperCase() + b.slice(1))
        .join(', ');

    // Extract specific vacation/PTO policy
    const vacationPolicy = (() => {
        // Look for specific vacation amounts
        const vacationAmount = text.match(/(\d+)\s*(?:weeks?|days?)\s*(?:of\s*)?(?:paid\s*)?(?:vacation|PTO|time off)/i);
        if (vacationAmount) {
            return `${vacationAmount[1]} ${vacationAmount[0].includes('week') ? 'weeks' : 'days'} vacation`;
        }

        // Look for unlimited/flexible policies
        if (text.match(/unlimited\s*(?:vacation|PTO|time off)/i)) {
            return 'Unlimited vacation';
        }

        if (text.match(/flexible\s*(?:vacation|PTO|time off)/i)) {
            return 'Flexible time off';
        }

        // Look for request-based policies
        if (text.match(/may request time off(?:\s*anytime)?(?:\s*with\s*(?:advanced\s*)?notice)?/i)) {
            const noticeMatch = text.match(/with\s*(advanced\s*)?notice/i);
            return noticeMatch ? 'Time off with advance notice' : 'Time off upon request';
        }

        return '';
    })();

    // Enhanced job title extraction
    let jobTitle = data.job_title || '';
    if (!jobTitle) {
        const titleMatch = text.match(/^([^.\n]+?)(?:\s*Expand|\n|$)/);
        jobTitle = titleMatch ? titleMatch[1].trim() : '';
    }

    // Enhanced experience level extraction - prioritize job-specific experience
    const jobExperienceMatch = text.match(/(\d+)(?:-(\d+))?\s*years?\s*(?:of\s*)?experience.*?(?:in|with).*?(?:full.?stack|development|technical|leadership)/i) ||
                               text.match(/looking for.*?(\d+)(?:-(\d+))?\s*years?\s*(?:of\s*)?experience/i) ||
                               text.match(/(\d+)(?:-(\d+))?\s*years?\s*(?:of\s*)?experience.*?(?:required|preferred|minimum)/i);

    const seniorityMatch = text.match(/(entry|junior|mid|senior|lead|principal|technical lead)\s*level/i) ||
                          text.match(/(beginner|intermediate|advanced|expert|senior)/i);

    let experienceLevel = '';
    if (jobExperienceMatch) {
        if (jobExperienceMatch[2]) {
            experienceLevel = `${jobExperienceMatch[1]}-${jobExperienceMatch[2]} years`;
        } else {
            experienceLevel = `${jobExperienceMatch[1]} years`;
        }
    } else if (seniorityMatch) {
        experienceLevel = seniorityMatch[1];
    }

    // Enhanced education extraction
    const educationMatch = text.match(/\b(Bachelor|Master|Ph\.?D\.?|Degree|Diploma|Certificate|Associates?)\b/gi) || [];
    const educationLevel = Array.from(new Set(educationMatch.map(e => e.toLowerCase())))
        .map(e => e.charAt(0).toUpperCase() + e.slice(1))
        .join(', ');

    return {
        // Basic Info
        url: data.url || '',
        scraped_data: text,
        job_title: jobTitle,
        company: data.company || '',
        company_name: companyInfo,
        company_size: companySize,
        industry: industry,

        // Compensation
        salary: salary,
        currency: salary ? 'USD' : '',
        bonus: '',
        equity: '',

        // Location & Work Type
        location: location,
        job_type: remoteStatus.toLowerCase(),
        position_type: '', 
        remote_status: remoteStatus,

        // Requirements
        experience: experienceLevel || requirements,
        education_level: educationLevel,
        certifications: '',

        // Skills & Technologies
        skills: uniqueSkills,
        tools: tools,
        software_tools: tools,
        programming_languages: programmingLanguages,
        platforms: platforms,

        // Job Details
        description: roleOverview || (responsibilities ? responsibilities.substring(0, 300) + '...' : '') || 
                    (text.split('\n').find(line => line.length > 100 && !line.includes('Expand')) || '').substring(0, 300),
        job_description_summary: roleOverview ? roleOverview.split('.').slice(0, 2).join('.') + '.' : 
                                (responsibilities ? responsibilities.split('.').slice(0, 2).join('.') + '.' : ''),
        responsibilities: responsibilities,
        requirements: requirements,

        // Work Schedule
        benefits: benefits,
        vacation_policy: vacationPolicy,
        working_days: workingDays,
        days_off: (() => {
            // Check for explicit mentions of days off
            if (text.match(/Saturday\s*(?:and|&)\s*Sunday|weekends/i)) {
                return 'Saturday & Sunday';
            }
            // Check for Monday-Friday schedule (implies weekend off)
            if (text.match(/Monday\s*(?:-|to|through|till)\s*Friday|Mon\s*(?:-|to)\s*Fri/i)) {
                return 'Saturday & Sunday';
            }
            // Check for 5 days per week (usually implies weekend off)
            if (text.match(/5\s*days?\s*(?:per\s*|a\s*)?week|five\s*days?\s*(?:per\s*|a\s*)?week/i)) {
                return 'Saturday & Sunday';
            }
            // Check for "may request time off" combined with other indicators
            if (text.match(/may request time off/i) && (text.match(/Monday.*Friday|Mon.*Fri|5.*days/i))) {
                return 'Saturday & Sunday';
            }
            return '';
        })(),
        hours_per_day: hoursPerDay,
        working_hours: workingHours,
        time_zone: timezone,
        shift_type: workingHours && /PM|pm/.test(workingHours.split('-')[1]) ? 'Evening' : '',

        // Timeline & Milestones
        start_date: text.match(/Within\s*(\d+)\s*days/i) ? text.match(/Within\s*(\d+)\s*days/i)[1] + ' days' : '',
        milestones: milestones,
        achievements_or_metrics: (text.match(/\$[\d,]+(?:\.\d+)?\s*(?:billion|million)|generating[\w\s\d\-]*revenues|millions?\s*of\s*emails|[\d,]+\s*users/gi) || []).join(', '),

        // Metadata
        last_scraped: data.last_scraped,
        scraper_status: data.scraper_status,
    };
});

// Get all incoming rows
const rows = $input.all().map(item => item.json);

// Filter out rows without a URL and standardize the structure
const filteredRows = rows.filter(row => {
  return row.job_description_url || 
         (row.job && row.job.description_url) ||
         row.url;
});

// Map to consistent output format
return filteredRows.map(row => {
  return {
    ...row,
    job_title: row.job_title || row.jsp.title,
    url: row.job_description_url || 
         (row.job ? row.job.description_url : null) || 
         row.url
  };
});
